            assert 'mean' in headers
            rows = list(reader)
            metrics = [row['metric'] for row in rows]
            assert 'win_rate' in metrics
            assert 'draw_rate' in metrics
            assert 'loss_rate' in metrics

    def test_benchmark_values_plausibility(self):
        try:
            import core
        except ImportError:
            pytest.skip('core.py not available')

        core.train_and_evaluate(csv_out_path=self.csv_file_path, n_runs=50, seed=42)

        with open(self.csv_file_path, 'r') as f:
            reader = csv.DictReader(f)
            rows = {row['metric']: row for row in reader}
            win_mean = float(rows['win_rate']['mean'])
            draw_mean = float(rows['draw_rate']['mean'])
            loss_mean = float(rows['loss_rate']['mean'])

            assert 0 <= win_mean <= 1
            assert 0 <= draw_mean <= 1
            assert 0 <= loss_mean <= 1
            assert abs(win_mean + draw_mean + loss_mean - 1.0) < 1e-06

